import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.RemoveActor{EntityUniqueID: -8589934592}
UNIQUE_ID = bytes.fromhex("ffffffff3f")

# generated by gophertunnel b8bd735:
# packet.RemoveActor{EntityUniqueID: -1}
NEGATIVE_ONE = bytes.fromhex("01")

# generated by gophertunnel b8bd735:
# packet.RemoveActor{EntityUniqueID: 300}
THREE_HUNDRED = bytes.fromhex("d804")

GOLDENS = [
    pytest.param(v2225.RemoveActorPacket(entity_id=-8589934592), UNIQUE_ID, id="wide-id"),
    pytest.param(v2225.RemoveActorPacket(entity_id=-1), NEGATIVE_ONE, id="negative-id-zigzags-to-one-byte"),
    pytest.param(v2225.RemoveActorPacket(entity_id=300), THREE_HUNDRED, id="id-above-127-is-a-two-byte-varint"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_remove_actor_is_packet_14(version):
    assert version.PACKETS[14] is version.RemoveActorPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_remove_actor_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_remove_actor_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
